  [1288298] = { { "Aggiunge l'insegna di questa professione al tuo giocattolo Orcish Tradeskill Sign per tutti i personaggi del tuo account.\n\nI personaggi che vogliono mostrare questa insegna devono conoscere quella professione.", "Aggiunge l'insegna di questa professione al tuo giocattolo Dwarven Tradeskill Sign per tutti i personaggi del tuo account.\n\nI personaggi che vogliono mostrare questa insegna devono conoscere quella professione.", shape = { "0/0", "0/0" }, key = { "cc1910f667ecb7bb", "f64e31761c01016d" } }, nil, 0x414b01b3, nil, "um" },
  [1288322] = { "Firma, sigla e data un lungo elenco di pagine che di sicuro non vale la pena leggere.\n\nVengono da una fonte affidabile, quindi probabilmente va tutto bene.", nil, 0xa2e6d836, nil, "um" },
  [1288387] = { "Assorbe $N1 danni, prosciugando mana al loro posto. Prosciuga $N2 mana per ogni danno assorbito.", "Assorbe i danni fisici, prosciugando mana al loro posto.", 0xbc8ec106, 0xd9625b22, "uu" },
  [1288388] = { "Richiama tre potenti stelle che si abbattono sulla posizione di Anara, infliggendo $N1 danni da arcano a tutti i giocatori entro $N2 m e respingendoli indietro.", nil, 0x9039d38e, nil, "um" },
  [1288447] = { nil, "Ala'ro viene prosciugato della sua vitalità.", nil, 0xa4167974, "mu" },
  [1288462] = { "Infligge danni da ombra a un nemico ogni $D1 per $D2.", "Danni da ombra inflitti ogni $D1.", 0x7b0a805b, 0x1bf49534, "uu" },
  [1288471] = { "Scaglia una glaive contro un nemico, infliggendo danni fisici e poi rimbalzando sui bersagli vicini.", nil, 0x2da9572c, nil, "um" },
  [1288479] = { "La Cacciatrice è potenziata dalla forza di Elune e conferisce agli alleati vicini velocità d'attacco e danni maggiori.", nil, 0x8d97dbc0, nil, "um" },
  [1288524] = { "Le vittime che si trovano sulla traiettoria della glaive subiscono danni fisici.", "$N1 danni fisici ogni $D1 finché la vittima non supera il $N3% della salute.", 0x9bde4a41, 0xbb3b3619, "uu" },
  [1288525] = { "Scaglia una glaive che ruota attorno all'incantatore per un breve periodo. I nemici che si trovano sulla sua traiettoria subiscono danni fisici.", nil, 0x46f7529f, nil, "um" },
  [1288548] = { nil, "Circondato da spine magiche che riducono del $N1% i danni subiti e riflettono $N2 di tutti i danni in arrivo.", nil, 0x4d187653, "mu" },
  [1288558] = { "Colpisce il bersaglio con una maledizione mortale che fa effetto dopo $D1. Allo scadere, infligge $N2 danni da ombra e riduce del $N3% i danni inflitti dal bersaglio.", "Infligge $N1 danni da ombra dopo $D1 e riduce del $N3% i danni inflitti.", 0x73442182, 0x5458c6b6, "uu" },
  [1288559] = { "Affligge il bersaglio con un veleno che attecchisce dopo $D1. Allo scadere di Fioritura, immobilizza il bersaglio sul posto, infliggendo ingenti danni da natura in $D2.", "$N1 danni da natura ogni $D1. Se non viene dissolto, il bersaglio viene immobilizzato sul posto per $D2.", 0x502f17af, 0x62f3c6a6, "uu" },
  [1288560] = { "Rallenta il bersaglio, riducendo del $N1% la sua velocità di movimento e la sua generazione di mana, rabbia ed energia.", "Velocità di movimento ridotta del $N1%. La tua generazione di mana, rabbia ed energia è ridotta.", 0x3bd0fdb4, 0x03fbd6cc, "uu" },
  [1288561] = { "Riduce di $N1 l'Armatura e le resistenze di un nemico per $D1. Finché è sotto l'effetto, il bersaglio non può usare la furtività o l'invisibilità.", "Armatura ridotta di $N1.\nImpossibile entrare in modalità furtiva o diventare invisibile.", 0x1decc690, 0x0730b87e, "uu" },
  [1288793] = { "Lancia un dardo di magia oscura contro un bersaglio nemico, infliggendo danni da ombra.", nil, 0x42ce8448, nil, "um" },
  [1288850] = { "Scaglia trappole a freccia congelanti contro più bersagli. Dopo $D1 le trappole si armano e congelano chiunque colpiscano, stordendolo per $D2 e infliggendo $N3 danni da gelo. Nel punto in cui si trovano si forma un'ampia lastra di ghiaccio che riduce la velocità di movimento dei nemici del $N4% e infligge $N5 danni da gelo ogni $D3.", nil, 0x5cf45d9c, nil, "um" },
  [1288908] = { "Colpisce il bersaglio attuale, infliggendo $N1 danni fisici e riducendone l'armatura del $N2%.", "Armatura ridotta del $N1%.", 0x05022d92, 0x7bc8160f, "uu" },
  [1288961] = { "Scatena una raffica di dardi sul punto in cui si trova il bersaglio, infliggendo ogni secondo danni fisici ai giocatori in un cono davanti all'incantatore per $D1.", "Scatena una raffica di dardi che infliggono $N1 danni fisici ai giocatori in un cono ogni secondo.", 0x1764e99f, 0xd6a4ce91, "uu" },
  [1288972] = { nil, "Danni fisici inflitti aumentati di $N1.\nVelocità d'attacco aumentata del $N2%.", nil, 0xbc6c8e1d, "mu" },
